Here is the root cause:
The bug arises from unnecessary calls to `rcu_nocb_flush_deferred_wakeup()` during user and guest mode transitions, which can lead to performance regressions when the nohz_full feature is not active on the local CPU. This results in a -3% performance hit as the system is polling for RCU wakeups that are not needed in those scenarios.

Here is the patch:
 #include <linux/livepatch.h>
 #include <linux/audit.h>
+#include <linux/tick.h>

 #include "common.h"

 static unsigned long exit_to_user_mode_loop(struct pt_regs *regs,
 					    unsigned long ti_work)
 {
 	/*
 	 * Before returning to user space ensure that all pending work
 	 * items have been completed.
 	 */
 	while (ti_work & EXIT_TO_USER_MODE_WORK) {

 		local_irq_enable_exit_to_user(ti_work);

 		if (ti_work & _TIF_NEED_RESCHED)
 			schedule();

 		if (ti_work & _TIF_UPROBE)
 			uprobe_notify_resume(regs);

 		if (ti_work & _TIF_PATCH_PENDING)
 			klp_update_patch_state(current);

 		if (ti_work & (_TIF_SIGPENDING | _TIF_NOTIFY_SIGNAL))
 			handle_signal_work(regs, ti_work);

 		if (ti_work & _TIF_NOTIFY_RESUME) {
 			tracehook_notify_resume(regs);
 			rseq_handle_notify_resume(NULL, regs);
 		}

 		/* Architecture specific TIF work */
 		arch_exit_to_user_mode_work(regs, ti_work);

 		/*
 		 * Disable interrupts and reevaluate the work flags as they
 		 * might have changed while interrupts and preemption was
 		 * enabled above.
 		 */
 		local_irq_disable_exit_to_user();

 		/* Check if any of the above work has queued a deferred wakeup */
-		rcu_nocb_flush_deferred_wakeup();
+		tick_nohz_user_enter_prepare();

 		ti_work = READ_ONCE(current_thread_info()->flags);
 	}

 	/* Return the latest work state for arch_exit_to_user_mode() */
 	return ti_work;
 }

 static void exit_to_user_mode_prepare(struct pt_regs *regs)
 {
 	unsigned long ti_work = READ_ONCE(current_thread_info()->flags);

 	lockdep_assert_irqs_disabled();

 	/* Flush pending rcuog wakeup before the last need_resched() check */
-	rcu_nocb_flush_deferred_wakeup();
+	tick_nohz_user_enter_prepare();

 	if (unlikely(ti_work & EXIT_TO_USER_MODE_WORK))
 		ti_work = exit_to_user_mode_loop(regs, ti_work);

 	arch_exit_to_user_mode_prepare(regs, ti_work);

 	/* Ensure that the address limit is intact and no locks are held */
 	addr_limit_user_check();
 	kmap_assert_nomap();
 	lockdep_assert_irqs_disabled();
 	lockdep_sys_exit();
 }



